Rules.InvariantScript:
Set(varReviewProject, Blank());
Set(varReviewComment, "");
Set(varReviewQueueMine, Coalesce(varReviewMineOnly, false));
Set(varReviewMineOnly, false);
ClearCollect(colRevReqs, AVCentralDepositRequests)

IfError(
    Patch(AVCentralDepositRequests,
        LookUp(AVCentralDepositRequests, ID = varReviewProject.ID),
        {
            Status: {Value: "Approved"},
            // Assignee(s) = the approver, plus any co-assignees selected in RV_Assignee.
            DG_Agency_Contact: Table({
                '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedUser",
                Claims: "i:0#.f|membership|" & Lower(User().Email),
                DisplayName: User().FullName,
                Email: User().Email,
                Department: "",
                JobTitle: "",
                Picture: ""
            }),
            ReviewedByContact: Table({
                '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedUser",
                Claims: "i:0#.f|membership|" & Lower(User().Email),
                DisplayName: User().FullName,
                Email: User().Email,
                Department: "",
                JobTitle: "",
                Picture: ""
            }),
            ReviewedDate: Now()
        }
    );
    Notify("Request approved.", NotificationType.Success);
    Set(varReviewProject, Blank());
    Set(varReviewComment, ""),
    Notify("Approve failed: " & FirstError.Message, NotificationType.Error)
)

IfError(
    Patch(AVCentralDepositRequests,
        LookUp(AVCentralDepositRequests, ID = varReviewProject.ID),
        {
            Status: {Value: "Rejected"},
            ReviewerComments: varReviewComment,
            ReviewedByContact: Table({
                '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedUser",
                Claims: "i:0#.f|membership|" & Lower(User().Email),
                DisplayName: User().FullName,
                Email: User().Email,
                Department: "",
                JobTitle: "",
                Picture: ""
            }),
            ReviewedDate: Now()
        }
    );
    Notify("Request rejected. The owner will see your comment on their next visit.", NotificationType.Warning);
    Set(varReviewProject, Blank());
    Set(varReviewComment, ""),
    Notify("Reject failed: " & FirstError.Message, NotificationType.Error)
)
